//! Triton-compiled Metal kernel dispatch for Moonshine encoder.
//!
//! Both Apple Silicon and Intel: loads pre-compiled .metallib binaries (zero runtime compilation).
//! Apple metallibs use Metal 3.1 (simdgroup), Intel metallibs use Metal 2.4 (scalar).
//! All generated by kernels/build.py + ninja, compiled via xcrun metal.

use anyhow::Result;
use candle_core::{DType, MetalDevice, MetalStorage, Shape, Storage, Tensor};
use candle_metal_kernels::metal::{Buffer, ComputePipeline};
use objc2_metal::MTLSize;
use std::sync::Arc;

// Auto-generated: kernel_data module, TritonKernels struct + load(),
// DecoderKernels struct + load().
include!("../kernels/out/generated/triton_metal_gen.rs");

// ── GpuBuffer: lightweight GPU buffer wrapper (same name on Metal + D3D12) ──

/// A Metal GPU buffer with byte offset. Same name as D3D12's GpuBuffer
/// to maximize code-sharing potential between platforms.
pub struct GpuBuffer {
    buffer: Arc<Buffer>,
    pub offset: usize, // byte offset into buffer
}

impl GpuBuffer {
    /// Allocate an uninitialized F16 buffer.
    pub fn alloc_f16(device: &MetalDevice, count: usize) -> Result<Self> {
        let buffer = device.new_buffer(count, DType::F16, "mb_f16")?;
        Ok(Self { buffer, offset: 0 })
    }

    /// Allocate an uninitialized F32 buffer.
    pub fn alloc_f32(device: &MetalDevice, count: usize) -> Result<Self> {
        let buffer = device.new_buffer(count, DType::F32, "mb_f32")?;
        Ok(Self { buffer, offset: 0 })
    }

    /// Create from F16 data (upload to GPU).
    pub fn from_f16_data(device: &MetalDevice, data: &[half::f16]) -> Result<Self> {
        let buffer = device.new_buffer_with_data(data)?;
        Ok(Self { buffer, offset: 0 })
    }

    /// Create from F32 data (upload to GPU).
    pub fn from_f32_data(device: &MetalDevice, data: &[f32]) -> Result<Self> {
        let buffer = device.new_buffer_with_data(data)?;
        Ok(Self { buffer, offset: 0 })
    }

    /// Get the underlying Metal buffer for dispatch.
    #[inline]
    pub fn buf(&self) -> &Buffer { &self.buffer }

    /// Raw pointer to buffer contents (for CPU read/write on shared buffers).
    #[inline]
    pub fn contents_ptr(&self) -> *mut u8 {
        unsafe { self.buffer.contents().add(self.offset) }
    }

    /// Create a view into this buffer at a byte offset.
    #[inline]
    pub fn with_offset(&self, byte_offset: usize) -> Self {
        Self {
            buffer: self.buffer.clone(),
            offset: self.offset + byte_offset,
        }
    }
}

fn cdiv(a: usize, b: usize) -> usize {
    (a + b - 1) / b
}

/// Set dynamic threadgroup memory for AIR kernels.
/// AIR kernels declare threadgroup memory as a function parameter (ptr addrspace(3)),
/// unlike MSL which uses static `threadgroup` declarations. This must be called before
/// dispatch for any AIR kernel that uses shared memory. Safe to call for MSL too (no-op).
#[cfg(target_arch = "aarch64")]
fn set_air_tg_mem(encoder: &candle_metal_kernels::metal::ComputeCommandEncoder, bytes: usize) {
    if bytes > 0 {
        encoder.set_threadgroup_memory_length(0, bytes);
    }
}

/// Determine threadgroup size for dispatch.
/// Clamps to the pipeline's max (critical for Intel GPUs with < 1024 limit).
fn tg_size(pipeline: &ComputePipeline, requested: usize) -> MTLSize {
    let max = pipeline.max_total_threads_per_threadgroup();
    MTLSize { width: requested.min(max), height: 1, depth: 1 }
}

/// Threadgroup size for matmul kernels.
/// On aarch64: 32x32 uses AIR (bs=128), larger tiles use MSL (simdgroup_matrix, 1024 threads).
#[cfg(target_arch = "aarch64")]
fn matmul_tg_size(pipeline: &ComputePipeline, block_m: usize, _block_n: usize) -> MTLSize {
    if block_m <= 32 { tg_size(pipeline, 128) } else { tg_size(pipeline, 1024) }
}
#[cfg(not(target_arch = "aarch64"))]
fn matmul_tg_size(pipeline: &ComputePipeline, _block_m: usize, _block_n: usize) -> MTLSize {
    tg_size(pipeline, 1024)
}

/// Threadgroup size for flash attention (MSL kernel uses 832 threads).
fn fa_tg_size(pipeline: &ComputePipeline) -> MTLSize {
    tg_size(pipeline, 832)
}

