/// Create an empty F16 output tensor on the Metal device.
pub fn empty_f16(device: &MetalDevice, shape: impl Into<Shape>) -> Result<Tensor> {
    let shape: Shape = shape.into();
    let n = shape.elem_count();
    let buffer = device.new_buffer(n, DType::F16, "triton_out")?;
    let storage = MetalStorage::new(buffer, device.clone(), n, DType::F16);
    Ok(Tensor::from_storage(
        Storage::Metal(storage),
        shape,
        candle_core::op::BackpropOp::none(),
        false,
    ))
}

/// Helper: extract MetalStorage from a tensor. Panics on non-Metal tensor.
macro_rules! with_metal_buffers {
    // 3 tensors + output
    ($a:expr, $b:expr, $c:expr, $out:expr, |$a_buf:ident, $a_off:ident, $b_buf:ident, $b_off:ident, $c_buf:ident, $c_off:ident, $o_buf:ident, $o_off:ident| $body:block) => {{
        let (sa, la) = $a.storage_and_layout();
        let (sb, lb) = $b.storage_and_layout();
        let (sc, lc) = $c.storage_and_layout();
        let (so, lo) = $out.storage_and_layout();
        let $a_off = la.start_offset() * $a.dtype().size_in_bytes();
        let $b_off = lb.start_offset() * $b.dtype().size_in_bytes();
        let $c_off = lc.start_offset() * $c.dtype().size_in_bytes();
        let $o_off = lo.start_offset() * $out.dtype().size_in_bytes();
        match (&*sa, &*sb, &*sc, &*so) {
            (Storage::Metal(ma), Storage::Metal(mb), Storage::Metal(mc), Storage::Metal(mo)) => {
                let $a_buf = ma.buffer();
                let $b_buf = mb.buffer();
                let $c_buf = mc.buffer();
                let $o_buf = mo.buffer();
                $body
            }
            _ => anyhow::bail!("All tensors must be on Metal device"),
        }
    }};
    // 2 tensors + output
    ($a:expr, $b:expr, $out:expr, |$a_buf:ident, $a_off:ident, $b_buf:ident, $b_off:ident, $o_buf:ident, $o_off:ident| $body:block) => {{
        let (sa, la) = $a.storage_and_layout();
        let (sb, lb) = $b.storage_and_layout();
        let (so, lo) = $out.storage_and_layout();
        let $a_off = la.start_offset() * $a.dtype().size_in_bytes();
        let $b_off = lb.start_offset() * $b.dtype().size_in_bytes();
        let $o_off = lo.start_offset() * $out.dtype().size_in_bytes();
        match (&*sa, &*sb, &*so) {
            (Storage::Metal(ma), Storage::Metal(mb), Storage::Metal(mo)) => {
                let $a_buf = ma.buffer();
                let $b_buf = mb.buffer();
                let $o_buf = mo.buffer();
                $body
            }
            _ => anyhow::bail!("All tensors must be on Metal device"),
        }
    }};
}

// ── Dispatch functions ──────────────────────────────────────────────────────

/// Dispatch matmul: C[M,N] = A[M,K] @ B[K,N]
///
/// B must be stored as [K, N] row-major (stride_bk=N, stride_bn=1).
/// The kernel's vec4 cooperative load requires the N dimension to be contiguous.
///
/// For weight matrices stored as [N, K] (e.g., from GGUF), transpose before calling:
///   `weight.t()?.contiguous()?`
pub fn triton_matmul(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    a: &Tensor,
    b: &Tensor,
    m: usize,
    n: usize,
    k: usize,
    block_m: usize,
    block_n: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, (m, n))?;

    with_metal_buffers!(a, b, &out, |a_buf, a_off, b_buf, b_off, o_buf, o_off| {
        let encoder = device.command_encoder()?;
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(a_buf), a_off);
        encoder.set_buffer(1, Some(b_buf), b_off);
        encoder.set_buffer(2, Some(o_buf), o_off);
        encoder.set_bytes(3, &(m as i32));
        encoder.set_bytes(4, &(n as i32));
        encoder.set_bytes(5, &(k as i32));
        encoder.set_bytes(6, &(k as i32));      // stride_am = K
        encoder.set_bytes(7, &1i32);            // stride_ak = 1
        encoder.set_bytes(8, &(n as i32));      // stride_bk = N (B=[K,N], row-major)
        encoder.set_bytes(9, &1i32);            // stride_bn = 1
        encoder.set_bytes(10, &(n as i32));     // stride_cm = N
        encoder.set_bytes(11, &1i32);           // stride_cn = 1

        let grid = MTLSize {
            width: cdiv(m, block_m),
            height: cdiv(n, block_n),
            depth: 1,
        };
        #[cfg(target_arch = "aarch64")]
        if block_m <= 32 { set_air_tg_mem(&encoder, 4096); }
        encoder.dispatch_thread_groups(grid, matmul_tg_size(pipeline, block_m, block_n));
        Ok::<(), anyhow::Error>(())
    })?;

    Ok(out)
}

/// Dispatch matmul + bias: C[M,N] = A[M,K] @ B[K,N] + bias[N]
